-- ============================================================================
-- SAHAYASETU / KERALA DISASTER RELIEF & REHABILITATION OS
-- SUPABASE RELATIONAL DATABASE SCHEMA & ROW-LEVEL SECURITY (RLS)
-- EXACT 4 CORE TABLES AS REQUESTED:
-- 1. users (User Details)
-- 2. regional_admins (Regional Admins Details - 14 District Officers)
-- 3. job_posts (Job Post / Civil Requisitions)
-- 4. disaster_details (Disaster Details - At Least 1 Per District, 14 Disasters)
-- ============================================================================

-- Enable required extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ----------------------------------------------------------------------------
-- CLEANUP UNUSED TABLES & REBUILD REQUESTED ENTITIES
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS public.approvals CASCADE;
DROP TABLE IF EXISTS public.job_requests CASCADE;
DROP TABLE IF EXISTS public.audit_logs CASCADE;
DROP TABLE IF EXISTS public.ngos CASCADE;
DROP TABLE IF EXISTS public.regions CASCADE;
DROP TABLE IF EXISTS public.job_listings CASCADE;
DROP VIEW IF EXISTS public.job_listings CASCADE;
DROP TABLE IF EXISTS public.regional_admins CASCADE;
DROP TABLE IF EXISTS public.job_posts CASCADE;
DROP TABLE IF EXISTS public.disaster_details CASCADE;

-- ============================================================================
-- 1. USER DETAILS (Displaced Citizens & Beneficiary Registrations)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.users (
    id TEXT PRIMARY KEY,
    auth_user_id UUID,
    name TEXT NOT NULL,
    email TEXT,
    phone TEXT NOT NULL,
    aadhaar_masked TEXT NOT NULL,
    ration_card_no TEXT,
    district_id TEXT,
    region_id TEXT,
    district_name TEXT NOT NULL DEFAULT 'Wayanad',
    camp_name TEXT NOT NULL,
    family_members_count INT NOT NULL DEFAULT 1,
    calamity TEXT NOT NULL,
    skills TEXT[] NOT NULL DEFAULT '{}',
    experience_years INT NOT NULL DEFAULT 0,
    living_status TEXT NOT NULL DEFAULT 'Relief Camp' CHECK (living_status IN ('Relief Camp', 'Makeshift', 'Host Family', 'Permanent Repaired')),
    daily_wage_tier NUMERIC NOT NULL DEFAULT 850,
    is_medical_fit BOOLEAN NOT NULL DEFAULT true,
    is_bio_verified BOOLEAN NOT NULL DEFAULT false,
    placement_status TEXT NOT NULL DEFAULT 'Available' CHECK (placement_status IN ('Available', 'Assigned', 'Resting', 'In-Review')),
    assigned_project_id TEXT,
    emergency_contact TEXT,
    bank_account_dbt JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Ensure all columns exist even if users table already existed previously
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS district_id TEXT;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS region_id TEXT;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS auth_user_id UUID;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS district_name TEXT DEFAULT 'Wayanad';
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS ration_card_no TEXT;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS family_members_count INT DEFAULT 1;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS living_status TEXT DEFAULT 'Relief Camp';
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS daily_wage_tier NUMERIC DEFAULT 850;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS is_medical_fit BOOLEAN DEFAULT true;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS is_bio_verified BOOLEAN DEFAULT false;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS placement_status TEXT DEFAULT 'Available';
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS assigned_project_id TEXT;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS emergency_contact TEXT;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS bank_account_dbt JSONB DEFAULT '{}'::jsonb;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now();

-- ============================================================================
-- 2. REGIONAL ADMINS DETAILS (14 Accredited District Relief Officers)
-- ============================================================================
CREATE TABLE public.regional_admins (
    id TEXT PRIMARY KEY,
    officer_credential_id TEXT NOT NULL UNIQUE,
    password TEXT NOT NULL,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    phone TEXT NOT NULL,
    district_id TEXT NOT NULL,
    district_name TEXT NOT NULL,
    ngo_name TEXT NOT NULL,
    ngo_darpan_id TEXT,
    sdma_officer_id TEXT,
    role TEXT NOT NULL DEFAULT 'regional-admin',
    status TEXT NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Suspended')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- 3. JOB POST (Rehabilitation Employment & Civil Reconstruction Requisitions)
-- ============================================================================
CREATE TABLE public.job_posts (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    agency TEXT NOT NULL,
    district_id TEXT NOT NULL,
    district_name TEXT NOT NULL,
    sector_location TEXT NOT NULL,
    priority TEXT NOT NULL DEFAULT 'SOS Urgent' CHECK (priority IN ('SOS Urgent', 'High Priority', 'Medium Standard')),
    required_skills TEXT[] NOT NULL DEFAULT '{}',
    required_count INT NOT NULL DEFAULT 1,
    assigned_count INT NOT NULL DEFAULT 0,
    daily_wage NUMERIC NOT NULL DEFAULT 850,
    hardship_allowance NUMERIC NOT NULL DEFAULT 150,
    duration_weeks INT NOT NULL DEFAULT 4,
    status TEXT NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Fulfilling', 'Completed')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Backward compatibility view for any components referencing job_listings
CREATE OR REPLACE VIEW public.job_listings AS 
SELECT * FROM public.job_posts;

-- ============================================================================
-- 4. DISASTER DETAILS (At Least 1 Official Disaster Per District across 14 Districts)
-- ============================================================================
CREATE TABLE public.disaster_details (
    id TEXT PRIMARY KEY,
    district_id TEXT NOT NULL UNIQUE,
    district_name TEXT NOT NULL,
    disaster_title TEXT NOT NULL,
    calamity_type TEXT NOT NULL,
    severity TEXT NOT NULL CHECK (severity IN ('Extreme Tier-1', 'High Tier-2', 'Moderate Tier-3')),
    affected_areas TEXT NOT NULL,
    active_relief_camps INT NOT NULL DEFAULT 1,
    displaced_persons_count INT NOT NULL DEFAULT 0,
    incident_date TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'Active Emergency' CHECK (status IN ('Active Emergency', 'Recovery Phase', 'Monitoring')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- ROW-LEVEL SECURITY (RLS) POLICIES
-- Clean, open policies allowing full client-side app access without permission errors
-- ============================================================================

ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.regional_admins ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.job_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.disaster_details ENABLE ROW LEVEL SECURITY;

-- 1. Users policies
DROP POLICY IF EXISTS "Allow all read users" ON public.users;
DROP POLICY IF EXISTS "Allow all insert users" ON public.users;
DROP POLICY IF EXISTS "Allow all update users" ON public.users;
DROP POLICY IF EXISTS "Allow all delete users" ON public.users;

CREATE POLICY "Allow all read users" ON public.users FOR SELECT USING (true);
CREATE POLICY "Allow all insert users" ON public.users FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow all update users" ON public.users FOR UPDATE USING (true);
CREATE POLICY "Allow all delete users" ON public.users FOR DELETE USING (true);

-- 2. Regional Admins policies
DROP POLICY IF EXISTS "Allow all read regional_admins" ON public.regional_admins;
DROP POLICY IF EXISTS "Allow all insert regional_admins" ON public.regional_admins;
DROP POLICY IF EXISTS "Allow all update regional_admins" ON public.regional_admins;
DROP POLICY IF EXISTS "Allow all delete regional_admins" ON public.regional_admins;

CREATE POLICY "Allow all read regional_admins" ON public.regional_admins FOR SELECT USING (true);
CREATE POLICY "Allow all insert regional_admins" ON public.regional_admins FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow all update regional_admins" ON public.regional_admins FOR UPDATE USING (true);
CREATE POLICY "Allow all delete regional_admins" ON public.regional_admins FOR DELETE USING (true);

-- 3. Job Posts policies
DROP POLICY IF EXISTS "Allow all read job_posts" ON public.job_posts;
DROP POLICY IF EXISTS "Allow all insert job_posts" ON public.job_posts;
DROP POLICY IF EXISTS "Allow all update job_posts" ON public.job_posts;
DROP POLICY IF EXISTS "Allow all delete job_posts" ON public.job_posts;

CREATE POLICY "Allow all read job_posts" ON public.job_posts FOR SELECT USING (true);
CREATE POLICY "Allow all insert job_posts" ON public.job_posts FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow all update job_posts" ON public.job_posts FOR UPDATE USING (true);
CREATE POLICY "Allow all delete job_posts" ON public.job_posts FOR DELETE USING (true);

-- 4. Disaster Details policies
DROP POLICY IF EXISTS "Allow all read disaster_details" ON public.disaster_details;
DROP POLICY IF EXISTS "Allow all insert disaster_details" ON public.disaster_details;
DROP POLICY IF EXISTS "Allow all update disaster_details" ON public.disaster_details;
DROP POLICY IF EXISTS "Allow all delete disaster_details" ON public.disaster_details;

CREATE POLICY "Allow all read disaster_details" ON public.disaster_details FOR SELECT USING (true);
CREATE POLICY "Allow all insert disaster_details" ON public.disaster_details FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow all update disaster_details" ON public.disaster_details FOR UPDATE USING (true);
CREATE POLICY "Allow all delete disaster_details" ON public.disaster_details FOR DELETE USING (true);

